from sklearn.metrics import mean_absolute_error
def forecast_ols(train, h):
    d=pd.DataFrame({'y':train.values, 't':np.arange(len(train)), 'month':train.index.month})
    d['logy']=np.log(d.y)
    # if all months enough? use category
    try:
        m=smf.ols('logy ~ t + C(month)', data=d).fit()
        fut=pd.DataFrame({'t':np.arange(len(train),len(train)+h), 'month':[(train.index[-1]+pd.DateOffset(months=i)).month for i in range(1,h+1)]})
        return np.exp(m.predict(fut)).values
    except Exception as e:
        return np.repeat(train.iloc[-1],h)
def forecast_snaive(train,h):
    return np.array([train.iloc[-12+i] if len(train)>=12 and i<12 else train.iloc[-1] for i in range(h)]) # for h=3 months after same month prev year? Actually target t+h uses value t+h-12 = train[-12+h]
def forecast_snaive_drift(train,h):
    vals=[]
    for i in range(1,h+1):
        if len(train)>=24:
            base=train.iloc[-12+i-1]
            growth=(train.iloc[-1]/train.iloc[-13]) # current month vs same last year
            vals.append(base*growth)
        elif len(train)>=12:
            vals.append(train.iloc[-12+i-1])
        else: vals.append(train.iloc[-1])
    return np.array(vals)
def forecast_ets(train,h):
    try:
        if len(train)>=24:
            return ExponentialSmoothing(train, trend='add', seasonal='add', seasonal_periods=12, initialization_method='estimated').fit(optimized=True).forecast(h).values
        else:
            return forecast_ols(train,h)
    except Exception as e:
        return forecast_ols(train,h)

methods={'snaive':forecast_snaive,'snaive_drift':forecast_snaive_drift,'ols':forecast_ols,'ets':forecast_ets}
